window.AUTH=window.AUTH||{};window.AUTH["93-1543"]={"d":"93-1543","id":"1994/93-1543","n":"McKennon v. Nashville Banner Publishing Co.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States and the Equal Employment Opportunity Commission as amici curiae","date":"","url":"https://www.justice.gov/osg/media/219631/dl?inline","side":"us","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/christine-mckennon-petitioner-v-nashville-banner-publishing-company","n":50}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep513/usrep513352/usrep513352.pdf","tr":false,"items":[{"t":"case","label":"ABF Freight System, Inc. v. NLRB","cite":"114 S. Ct. 835","y":1994,"url":"https://www.courtlistener.com/c/S.%20Ct./114/835/","sc":1,"by":{"0":"22"}},{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","id":"1974/74-389","sc":1,"op":2,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"0":"10, 11, 17, 19, 21-22, 25"}},{"t":"case","label":"Arizona Governing Committee v. Norris","cite":"463 U.S. 1073","id":"1982/82-52","sc":1,"sum":"The State's retirement plan discriminates on the basis of sex in violation of Title VII, and all retirement benefits derived from contributions made after this decision must be calculated without regard to the beneficiary's sex. But benefits derived from contributions made prior to this decision may be calculated as provided by the existing terms of the Arizona plan. 671 F. 2d 330, affirmed in part, reversed in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Bonger v. American Water Works","cite":"789 F. Supp. 1102","y":1992,"court":"D. CoIo.","url":"https://www.courtlistener.com/c/F.%20Supp./789/1102/","by":{"0":"17, 19"}},{"t":"case","label":"Calloway v. Partners Nat. Health Plans","cite":"986 F.2d 446","y":1993,"court":"llth Cir.","url":"https://www.courtlistener.com/c/F.2d/986/446/","by":{"0":"16"}},{"t":"case","label":"Churchman v. Pinkerton's Inc.","cite":"756 F. Supp. 515","y":1991,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./756/515/","by":{"0":"17"}},{"t":"case","label":"Darby v. Pasadena Police Dep't","cite":"939 F.2d 311","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/939/311/","by":{"0":"25"}},{"t":"case","label":"DeVoe v. Medi-Dyn, Inc.","cite":"782 F. Supp. 546","y":1992,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./782/546/","by":{"0":"17"}},{"t":"case","label":"EEOC v. Goodyear Aerospace Corp.","cite":"813 F.2d 1539","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/1539/","by":{"0":"23"}},{"t":"case","label":"EEOC v. Harris Cernin, Inc.","cite":"10 F.3d 1286","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/10/1286/","by":{"0":"23"}},{"t":"case","label":"EEOC v. Recruit U. S. A., Inc.","cite":"939 F.2d 746","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/939/746/","by":{"0":"16"}},{"t":"case","label":"Franks v. Bowman Transportation Co.","cite":"424 U.S. 747","y":1976,"id":"1975/74-728","sc":1,"op":3,"sum":"In a class action against respondent employer and certain labor unions (of which respondent union is the successor) petitioners alleged various racially discriminatory employment practices in violation of Title VII of the Civil Rights Act of 1964 (Act), especially with respect to employment of over-the-road (OTR) truck drivers. After certifying the action as a class action and, inter alia, designating one of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 11, 12, 20"}},{"t":"case","label":"Johnson v. Honeywell Information Systems, Inc.","cite":"955 F.2d 409","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/955/409/","op":2,"sum":"Noting the need \"to prevent an employer from combing a dis- charged employee's record for evidence of any and all misrepresenta- tions, no matter how minor or trivial, in an effort to avoid legal responsibility for an otherwise impermissible discharge\".","sumSrc":"brief:0","by":{"0":"3,4, 18-19"}},{"t":"case","label":"Kristufek v. Hussmann Food service Co.","cite":"985 F.2d 364","y":1993,"court":"7thCir.","url":"https://www.courtlistener.com/c/F.2d/985/364/","op":1,"by":{"0":"7, 9, 16, 25"}},{"t":"case","label":"Landgraf v. USI Film Products","cite":"114 S. Ct. 1483","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Los Angeles Dep't of Water& Power v. Manhart","cite":"435 U.S. 702","id":"1977/76-1810","sc":1,"sum":"The Court held that the company’s policy was based on aggregate numbers that are not necessarily true for individuals, which violates the Civil Rights Act prohibition of individual discrimination based purely on gender.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Louisiana v. United States","cite":"380 U.S. 145","y":1965,"id":"1964/67","sc":1,"sum":"The Supreme Court held that the Louisiana constitution's voter registration requirements are unconstitutional. With Justice Hugo L. Black writing for the majority, the Court reasoned that the registration provisions stood in conflict with the Fifteenth Amendment's and 42 U.S.C. § 1971(a)'s prohibitions against discrimination in voting because of race.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Mathis v. Boeing Military Airplane Co.","cite":"719 F. Supp. 991","y":1989,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./719/991/","by":{"0":"17"}},{"t":"case","label":"Milligan-Jensen v. Michigan Technological Univ.","cite":"975 F.2d 302","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/975/302/","op":2,"by":{"0":"4,7, 15"}},{"t":"case","label":"Mitchell Bros. Film Group v. Cinema Adult Theater","cite":"604 F.2d 852","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/604/852/","by":{"0":"15-16"}},{"t":"case","label":"Mt. Healthy City School District Board of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"op":2,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"0":"14, 15, 21"}},{"t":"case","label":"O'Day v. McDonnell Douglas Helicopter Co.","cite":"784 F. Supp. 1466","y":1992,"court":"D. Ariz.","url":"https://www.courtlistener.com/c/F.%20Supp./784/1466/","by":{"0":"17,19"}},{"t":"case","label":"O'Driscoll v. Hercules, Inc.","cite":"745 F. Supp. 656","y":1990,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp./745/656/","by":{"0":"7, 17, 19"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"op":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10-11"}},{"t":"case","label":"Perma Life Mufflers, Inc. v. International Parts Corp.","cite":"392 U.S. 134","y":1968,"id":"1967/733","sc":1,"op":2,"sum":"Petitioners, dealers who had operated \"Midas Muffler Shops,\" brought this antitrust action for treble damages against respondent Midas, Inc., its parent corporation (International), two other subsidiaries, and corporate officers and agents, charging an illegal conspiracy in violation of § 1 of the Sherman Act, and violations of § 3 of the Clayton Act and § 2 as amended by the RobinsonPatman Act. Petitioners attacked …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"op":2,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"9, 15, 21, 23, 24"}},{"t":"case","label":"Punahele v. United Air Lines, Inc.","cite":"756 F. Supp. 656","y":1990,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp./756/656/","by":{"0":"17"}},{"t":"case","label":"Reed v. Amax Coal Co.","cite":"971 F.2d 1295","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/971/1295/","sum":"Noting need \"to prevent employers from avoiding Title VII liability by pointing to minor rule violations which may technically subject the employee to dismissal but would not, in fact, result in discharge\".","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Smallwood v. United Air Lines, Inc.","cite":"728 F.2d 614","y":1984,"url":"https://www.courtlistener.com/c/F.2d/728/614/","op":1,"by":{"0":"9, 20"}},{"t":"case","label":"Smith v. General Scanning, Inc.","cite":"876 F.2d 1315","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/876/1315/","by":{"0":"16"}},{"t":"case","label":"Summers v. State Farm Mutual Automobile Ins. Co.","cite":"864 F.2d 700","y":1988,"court":"lOth Cir.","url":"https://www.courtlistener.com/c/F.2d/864/700/","op":3,"by":{"0":"3, 13, 14, 15, 16, 20"}},{"t":"case","label":"Trans World Airlines, Inc. v. Thurston","cite":"469 U.S. 111","id":"1984/83-997","sc":1,"op":1,"sum":"The Age Discrimination in Employment Act (ADEA) was amended in 1978 to prohibit the mandatory retirement of a protected employee because of his age. Concerned that its retirement policy, at least as it applied to flight engineers, violated the ADEA, petitioner Trans World Airlines (TWA) adopted a plan permitting any employee in \"flight engineer status\" at age 60 to continue working in that capacity. The plan, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"United States v. N. L. Industries, Inc.","cite":"479 F.2d 354","y":1973,"court":"8thCir.","url":"https://www.courtlistener.com/c/F.2d/479/354/","by":{"0":"11"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","by":{"0":"7, 9, 15, 16, 17, 19, 20, 24, 25"}},{"t":"case","label":"Washington v. Lake County","cite":"969 F.2d 250","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/969/250/","op":1,"by":{"0":"7, 18, 19"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)(l)","(d)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"2, 5, 7, 22, 5"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"0":"5, 8, 13, 23"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","stext":{"head":"§12101. Findings and purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) physical or mental disabilities in no way diminish a person's right to fully participate in all aspects of society, yet many people with physical or mental disabilities have been precluded from doing so because of discrimination; others who have a record of a disability or are regarded as having a disability also have been subjected to discrimination;"],[1,"(2) historically, society has tended to isolate and segregate individuals with disabilities, and, despite some improvements, such forms of discrimination against individuals with disabilities continue to be a serious and pervasive social problem;"],[1,"(3) discrimination against individuals with disabilities persists in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and access to public services;"],[1,"(4) unlike individuals who have experienced discrimination on the basis of race, color, sex, national origin, religion, or age, individuals who have experienced discrimination on the basis of disability have often had no legal recourse to redress such discrimination;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination, including outright intentional exclusion, the discriminatory effects of architectural, transportation, and communication barriers, overprotective rules and policies, failure to make modifications to existing facilities and practices, exclusionary qualification standards and criteria, segregation, and relegation to lesser services, programs, activities, benefits, jobs, or other opportunities;"],[1,"(6) census data, national polls, and other studies have documented that people with disabilities, as a group, occupy an inferior status in our society, and are severely disadvantaged socially, vocationally, economically, and educationally;"],[1,"(7) the Nation's proper goals regarding individuals with disabilities are to assure equality of opportunity, full participation, independent living, and economic self-sufficiency for such individuals; and"],[1,"(8) the continuing existence of unfair and unnecessary discrimination and prejudice denies people with disabilities the opportunity to compete on an equal basis and to pursue those opportunities for which our free society is justifiably famous, and costs the United States billions of dollars in unnecessary expenses resulting from dependency and nonproductivity."],[0,"(b) Purpose"],[0,"It is the purpose of this chapter—"],[1,"(1) to provide a clear and comprehensive national mandate for the elimination of discrimination against individuals with disabilities;"],[1,"(2) to provide clear, strong, consistent, enforceable standards addressing discrimination against individuals with disabilities;"],[1,"(3) to ensure that the Federal Government plays a central role in enforcing the standards established in this chapter on behalf of individuals with disabilities; and"],[1,"(4) to invoke the sweep of congressional authority, including the power to enforce the fourteenth amendment and to regulate commerce, in order to address the major areas of discrimination faced day-to-day by people with disabilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12101. Findings and purpose","tname":"The Public Health and Welfare","by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 2000et","url":"https://www.law.cornell.edu/uscode/text/42/2000et","by":{"0":"passim"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(l)","(g)(2)(A)","(g)(2)(B)"],"by":{"0":"8, 8, 21"}},{"t":"law","label":"Pub. L. No. 102-166","url":"https://www.govinfo.gov/link/statute/105/1075","by":{"0":"21"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Minimum wage","tname":"Labor","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"passim"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§216. Penalties","tname":"Labor","by":{"0":"8"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","by":{"0":"8"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(c)"],"by":{"0":"7"}}]};